$(document).ready(function(){$("#volunteerListContainer").length&&loadVolunteers(),$("#volunteerFilterForm").on("submit",function(e){e.preventDefault(),loadVolunteers($(this).serialize())}),$(document).on("change",".status-selector",function(){const e=$(this).data("id"),t=$(this).val(),o=$(this);o.prop("disabled",!0),$.post("volunteer-status.php",{id:e,status:t},function(e){o.prop("disabled",!1),"success"===e.status&&Swal.fire({icon:"success",title:"Updated",text:"Status changed to "+t,toast:!0,position:"top-end",timer:3e3,showConfirmButton:!1})})})});function loadVolunteers(e=""){$.post("volunteer-list.php",e,function(e){$("#volunteerListContainer").html(e)}).fail(function(){$("#volunteerListContainer").html('<div class="alert alert-danger m-3">Failed to load volunteers. Please ensure the database table exists and you are logged in.</div>'),console.error("AJAX Error: Could not load volunteer-list.php")})}function deleteVolunteer(e){Swal.fire({title:"Are you sure?",text:"This record and photo will be permanently deleted!",icon:"warning",showCancelButton:!0,confirmButtonColor:"#d33",confirmButtonText:"Yes, delete it!"}).then(t=>{t.isConfirmed&&$.post("volunteer-delete.php",{id:e},function(e){loadVolunteers(),Swal.fire("Deleted!","Volunteer has been removed.","success")})})}function generateID(e){$.post("volunteer-idcard.php",{id:e},function(e){$("#idCardContainer").html(e),$("#idCardModal").modal("show")})}function viewVolunteer(e){$.post("volunteer-view.php",{id:e},function(e){$("#modalContent").html(e),$("#volunteerModal").modal("show")})}
